#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

banner "lead-radar production setup"

stage "Supabase: project and access token"
say "Create or choose the Supabase project that will run lead-radar."
open_url "https://supabase.com/dashboard/new"
step "Create a Free project, or open an existing one. Use a strong database password and save it in your password manager."
step "Copy the project ref from Project Settings -> General. It is the short lowercase identifier in the project URL."
ask SUPABASE_PROJECT_REF "Project ref:"
write_env SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"
open_url "https://supabase.com/dashboard/account/tokens"
step "Create a personal access token for the Supabase CLI and copy it."
ask_secret SUPABASE_ACCESS_TOKEN "Supabase access token:"
write_env SUPABASE_ACCESS_TOKEN "$SUPABASE_ACCESS_TOKEN"

stage "Supabase: database connection string"
say "Edge Functions connect through the shared pooler in transaction mode."
open_url "https://supabase.com/dashboard/project/$SUPABASE_PROJECT_REF/settings/database"
step "Open Connect, choose the shared pooler / transaction mode connection string, and copy the full URI."
step "Replace the password placeholder with the database password before pasting it here."
ask_secret SUPABASE_DB_URL "SUPABASE_DB_URL:"
write_env SUPABASE_DB_URL "$SUPABASE_DB_URL"

stage "Alerting: Discord and heartbeat"
say "Discord receives lead and operational alerts. Healthchecks receives the external dead-man heartbeat."
open_url "https://discord.com/channels/@me"
step "In the target Discord server: channel settings -> Integrations -> Webhooks -> New Webhook -> Copy Webhook URL."
ask_secret DISCORD_WEBHOOK_URL "Discord webhook URL:"
write_env DISCORD_WEBHOOK_URL "$DISCORD_WEBHOOK_URL"
open_url "https://healthchecks.io/projects/"
step "Create one check with a 2 minute period and 5 minute grace time, then copy its ping URL."
ask_secret HEALTHCHECKS_PING_URL "Healthchecks ingest ping URL:"
write_env HEALTHCHECKS_PING_URL "$HEALTHCHECKS_PING_URL"
step "Optional: create a second 20 minute check for the canary. Paste its ping URL, or press Enter to leave blank."
ask_secret HEALTHCHECKS_CANARY_PING_URL "Canary ping URL (optional):"
write_env HEALTHCHECKS_CANARY_PING_URL "$HEALTHCHECKS_CANARY_PING_URL"
step "Optional: paste a GitHub token with public_repo/read-only search access for higher GitHub Search rate limits."
ask_secret GITHUB_TOKEN "GitHub token (optional):"
write_env GITHUB_TOKEN "$GITHUB_TOKEN"

stage "Generate and deploy Edge Function secrets"
INGEST_SHARED_SECRET="${INGEST_SHARED_SECRET:-$(_existing INGEST_SHARED_SECRET || true)}"
CANARY_SHARED_SECRET="${CANARY_SHARED_SECRET:-$(_existing CANARY_SHARED_SECRET || true)}"
DASHBOARD_ACCESS_TOKEN="${DASHBOARD_ACCESS_TOKEN:-$(_existing DASHBOARD_ACCESS_TOKEN || true)}"
[[ -n "$INGEST_SHARED_SECRET" ]] || INGEST_SHARED_SECRET="$(openssl rand -hex 32)"
[[ -n "$CANARY_SHARED_SECRET" ]] || CANARY_SHARED_SECRET="$(openssl rand -hex 32)"
[[ -n "$DASHBOARD_ACCESS_TOKEN" ]] || DASHBOARD_ACCESS_TOKEN="$(openssl rand -hex 32)"
write_env INGEST_SHARED_SECRET "$INGEST_SHARED_SECRET"
write_env CANARY_SHARED_SECRET "$CANARY_SHARED_SECRET"
write_env DASHBOARD_ACCESS_TOKEN "$DASHBOARD_ACCESS_TOKEN"
say "The wizard will now link the project, push migrations, deploy three functions, and set encrypted function secrets."
if confirm "Run Supabase CLI deployment now?"; then
  export SUPABASE_ACCESS_TOKEN
  npx --yes supabase@latest link --project-ref "$SUPABASE_PROJECT_REF"
  npx --yes supabase@latest db push --remote --yes
  npx --yes supabase@latest functions deploy ingest-tick canary dashboard-api --remote --no-verify-jwt
  secret_args=(
    "SUPABASE_DB_URL=$SUPABASE_DB_URL"
    "DISCORD_WEBHOOK_URL=$DISCORD_WEBHOOK_URL"
    "INGEST_SHARED_SECRET=$INGEST_SHARED_SECRET"
    "CANARY_SHARED_SECRET=$CANARY_SHARED_SECRET"
    "DASHBOARD_ACCESS_TOKEN=$DASHBOARD_ACCESS_TOKEN"
    "HEALTHCHECKS_PING_URL=$HEALTHCHECKS_PING_URL"
  )
  [[ -n "$HEALTHCHECKS_CANARY_PING_URL" ]] && secret_args+=("HEALTHCHECKS_CANARY_PING_URL=$HEALTHCHECKS_CANARY_PING_URL")
  [[ -n "$GITHUB_TOKEN" ]] && secret_args+=("GITHUB_TOKEN=$GITHUB_TOKEN")
  npx --yes supabase@latest secrets set "${secret_args[@]}"
else
  SKIPPED+=("Supabase CLI deployment")
fi

stage "Supabase: create cron jobs"
sed \
  -e "s/__PROJECT_REF__/$SUPABASE_PROJECT_REF/g" \
  -e "s/__INGEST_SECRET__/$INGEST_SHARED_SECRET/g" \
  -e "s/__CANARY_SECRET__/$CANARY_SHARED_SECRET/g" \
  supabase/cron-setup.sql > .lead-radar-cron.generated.sql
say "Cron cannot be safely created without one SQL-editor step because it must create Vault secrets inside your project."
open_url "https://supabase.com/dashboard/project/$SUPABASE_PROJECT_REF/sql/new"
step "Open .lead-radar-cron.generated.sql from this repository, copy the whole file into the SQL editor, and run it."
warn "The generated file contains the two cron shared secrets. Delete it after the SQL succeeds."
if confirm "I ran the cron SQL successfully"; then
  rm -f .lead-radar-cron.generated.sql
  printf '  %s✓ removed%s .lead-radar-cron.generated.sql\n' "$GREEN" "$RESET"
else
  SKIPPED+=("cron SQL remains in .lead-radar-cron.generated.sql")
fi

stage "Dashboard: enable static hosting"
say "This repo already includes .github/workflows/deploy-pages.yml for the zero-cost static dashboard."
open_url "https://github.com/definitelynotguru/lead-radar/settings/pages"
step "Set GitHub Pages Source to 'GitHub Actions'. The next push to main builds and deploys web/dist."
step "Cloudflare Pages also works: build command 'npm --prefix web run build', output directory 'web/dist', root directory repository root."
pause "Press Enter after enabling Pages or deciding to defer hosting"

stage "Verify production"
say "Checking that the deployed ingest and canary functions answer authenticated requests."
ingest_code=$(curl -sS -o /dev/null -w '%{http_code}' -X POST -H "x-lead-radar-secret: $INGEST_SHARED_SECRET" "https://$SUPABASE_PROJECT_REF.supabase.co/functions/v1/ingest-tick" || true)
canary_code=$(curl -sS -o /dev/null -w '%{http_code}' -X POST -H "x-lead-radar-secret: $CANARY_SHARED_SECRET" "https://$SUPABASE_PROJECT_REF.supabase.co/functions/v1/canary" || true)
say "ingest-tick HTTP $ingest_code; canary HTTP $canary_code. 200 or 207 means the function ran; 207 means a reported check is degraded."
step "Open the deployed static dashboard, paste https://$SUPABASE_PROJECT_REF.supabase.co/functions/v1/dashboard-api and the owner token from .env."
note "The first tick backfills incrementally. HN can take several minutes because it intentionally fetches only 20 comments per tick."

finish
}

run_wizard "$@"; exit
